import{_ as p,W as o,s as d,u as c,I as l,ah as i,Z as a,w as n,A as t}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const k=JSON.parse('{"title":"如何在 CentOS 8/RHEL 8 上安装 Ansible（自动化工具） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8/RHEL 8 上安装 Ansible（自动化工具） | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8/RHEL 8 上安装 Ansible（自动化工具） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8/RHEL 8 上安装 Ansible（自动化工具） | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191125 How to Install Ansible (Automation Tool) on CentOS 8-RHEL 8","title":"如何在 CentOS 8/RHEL 8 上安装 Ansible（自动化工具）","tag":"201912"},"relativePath":"201912/20191125 How to Install Ansible (Automation Tool) on CentOS 8-RHEL 8.md","filePath":"[post].md"}'),r={name:"201912/20191125 How to Install Ansible (Automation Tool) on CentOS 8-RHEL 8.md"};function u(h,s,b,g,v,m){const e=o("Link");return c(),d("div",null,[l("p",null,[a(e,{href:"collector:",title:"lujun9972"},{default:t(()=>s[0]||(s[0]=[n("#")])),_:1}),s[5]||(s[5]=n(": subject: (How to Install Ansible (Automation Tool) on CentOS 8/RHEL 8) ")),a(e,{href:"collector:",title:"lujun9972"},{default:t(()=>s[1]||(s[1]=[n("#")])),_:1}),s[6]||(s[6]=n(": via: (")),a(e,{href:"https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/"},{default:t(()=>s[2]||(s[2]=[n("https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/")])),_:1}),s[7]||(s[7]=n(") ")),a(e,{href:"collector:",title:"lujun9972"},{default:t(()=>s[3]||(s[3]=[n("#")])),_:1}),s[8]||(s[8]=n(": author: (Pradeep Kumar ")),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>s[4]||(s[4]=[n("https://www.linuxtechi.com/author/pradeep/")])),_:1}),s[9]||(s[9]=n(")"))]),s[28]||(s[28]=i('<h1 id="如何在-centos-8-rhel-8-上安装-ansible-自动化工具" tabindex="-1">如何在 CentOS 8/RHEL 8 上安装 Ansible（自动化工具） <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安装-ansible-自动化工具" aria-label="Permalink to 如何在 CentOS 8/RHEL 8 上安装 Ansible（自动化工具）">​</a></h1><p>Ansible 是给 Linux 系统管理员使用的出色自动化工具。它是一种开源配置工具，能让系统管理员可以从一个中心节点（即 Ansible 服务器）管理数百台服务器。将 Ansible 与 Puppet、Chef 和 Salt 等类似工具进行比较时，它是首选的配置工具，因为它不需要任何代理，并且可以工作在 SSH 和 python 上。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201912/01/223012czkxt6dhku6snhxn.jpg" alt=""></p><p>在本教程中，我们将学习如何在 CentOS 8 和 RHEL 8 系统上安装和使用 Ansble。</p><p>Ansible 实验环境信息：</p><ul><li>最小化安装的 CentOS 8 / RHEL 8 服务器（192.168.1.10），且有互联网连接</li><li>两个 Ansible 节点 - Ubuntu 18.04 LTS （192.168.1.20） 和 CentOS 7 （192.168.1.30）</li></ul><h3 id="centos-8-上的-ansible-安装步骤" tabindex="-1">CentOS 8 上的 Ansible 安装步骤 <a class="header-anchor" href="#centos-8-上的-ansible-安装步骤" aria-label="Permalink to CentOS 8 上的 Ansible 安装步骤">​</a></h3>',7)),l("p",null,[s[11]||(s[11]=n("Ansible 包不在 CentOS 8 默认的软件包仓库中。因此，我们需要执行以下命令启用 ")),a(e,{href:"http://www.linuxtechi.com/enable-epel-repo-centos8-rhel8-server/"},{default:t(()=>s[10]||(s[10]=[n("EPEL 仓库")])),_:1}),s[12]||(s[12]=n("："))]),s[29]||(s[29]=i(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm -y</span></span></code></pre></div><p>启用 epel 仓库后，执行以下 <code>dnf</code> 命令安装 Ansible：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install ansible</span></span></code></pre></div><p>上面命令的输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/dnf-install-ansible-centos8-1536x652.png" alt="dnf-install-ansible-centos8"></p><p>成功安装 Ansible 后，运行以下命令验证它的版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo ansible --version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Ansible-version-CentOS8.png" alt="Ansible-version-CentOS8"></p><p>上面的输出确认在 CentOS 8 上安装完成。</p><p>让我们看下 RHEL 8 系统。</p><h3 id="rhel-8-上的-ansible-安装步骤" tabindex="-1">RHEL 8 上的 Ansible 安装步骤 <a class="header-anchor" href="#rhel-8-上的-ansible-安装步骤" aria-label="Permalink to RHEL 8 上的 Ansible 安装步骤">​</a></h3><p>如果你有有效的 RHEL 8 订阅，请使用以下订阅管理器命令启用 Ansble 仓库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo subscription-manager repos --enable ansible-2.8-for-rhel-8-x86_64-rpms</span></span></code></pre></div><p>启用仓库后，执行以下 <code>dnf</code> 命令安装 Ansible：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install ansible -y</span></span></code></pre></div><p>安装 Ansible 及其依赖包后，执行以下命令来验证它的版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo ansible --version</span></span></code></pre></div><h3 id="在-centos-8-rhel-8-上通过-pip3-安装-ansible-的可选方法" tabindex="-1">在 CentOS 8 / RHEL 8 上通过 pip3 安装 Ansible 的可选方法 <a class="header-anchor" href="#在-centos-8-rhel-8-上通过-pip3-安装-ansible-的可选方法" aria-label="Permalink to 在 CentOS 8 / RHEL 8 上通过 pip3 安装 Ansible 的可选方法">​</a></h3><p>如果你希望使用 <code>pip</code>（Python 的包管理器）安装 Ansible，请首先使用以下命令安装 pyhton3 和 python3-pip 包：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo dnf install python3 python3-pip -y</span></span></code></pre></div><p>安装 python3 后，运行以下命令来验证它的版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ python3 -V</span></span>
<span class="line"><span>Python 3.6.8</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>用下面的 <code>pip3</code> 命令安装 Ansible：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ pip3 install ansible --user</span></span></code></pre></div><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/Ansible-Install-pip3-centos8-1536x545.png" alt="Ansible-Install-pip3-centos8"></p><p>上面的输出确认 Ansible 已成功使用 <code>pip3</code> 安装。让我们看下如何使用 Ansible。</p><h3 id="如何使用-ansible-自动化工具" tabindex="-1">如何使用 Ansible 自动化工具？ <a class="header-anchor" href="#如何使用-ansible-自动化工具" aria-label="Permalink to 如何使用 Ansible 自动化工具？">​</a></h3><p>当我们使用 <code>yum</code> 或 <code>dnf</code> 命令安装 Ansible 时，它的配置文件、清单文件和角色目录会自动在 <code>/etc/ansible</code> 文件夹下创建。</p><p>让我们添加一个名称为 <code>labservers</code> 的组，并在 <code>/etc/ansible/hosts</code> 文件中给该组添加上述的 Ubuntu 18.04 和 CentOS 7 系统的 IP 地址：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ sudo vi /etc/ansible/hosts</span></span>
<span class="line"><span>…</span></span>
<span class="line"><span>[labservers]</span></span>
<span class="line"><span>192.168.1.20</span></span>
<span class="line"><span>192.168.1.30</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>保存并退出文件。</p><p>更新清单文件（<code>/etc/ansible/hosts</code>）后，将用户的 ssh 公钥放到属于 <code>labservers</code> 组的远程系统。</p><p>让我们首先使用 <code>ssh-keygen</code> 命令生成本地用户的公钥和私钥：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ ssh-keygen</span></span></code></pre></div><p>现在使用以下命令在 Ansible 服务器及其客户端之间交换公钥：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ ssh-copy-id root@linuxtechi</span></span>
<span class="line"><span>[root@linuxtechi ~]$ ssh-copy-id root@linuxtechi</span></span></code></pre></div><p>现在，让我们尝试几个 Ansible 命令，首先使用 <code>ping</code> 模块验证 Ansible 服务器与客户端的连接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ ansible -m ping &quot;labservers&quot;</span></span></code></pre></div><p>注意： 如果我们没有在上面的命令中指定清单文件，那么它将引用默认主机文件（即 <code>/etc/ansible/hosts</code>）。</p><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/11/ansible-ping-module-centos8.png" alt="ansible-ping-module-centos8"></p><p>让我们使用 Ansible shell 命令检查每个客户端的内核版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ ansible -m command -a &quot;uname -r&quot; &quot;labservers&quot;</span></span>
<span class="line"><span>192.168.1.30 | CHANGED | rc=0 &gt;&gt;</span></span>
<span class="line"><span>4.15.0-20-generic</span></span>
<span class="line"><span>192.168.1.20 | CHANGED | rc=0 &gt;&gt;</span></span>
<span class="line"><span>3.10.0-327.el7.x86_64</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>使用以下命令列出清单文件中的所有主机：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@linuxtechi ~]$ ansible all -i /etc/ansible/hosts --list-hosts</span></span>
<span class="line"><span>  hosts (4):</span></span>
<span class="line"><span>    192.168.100.1</span></span>
<span class="line"><span>    192.168.100.10</span></span>
<span class="line"><span>    192.168.1.20</span></span>
<span class="line"><span>    192.168.1.30</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>使用以下 Ansible 命令仅列出 <code>labservers</code> 组中的主机：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@linuxtechi ~]$ ansible labservers -i /etc/ansible/hosts --list-hosts</span></span>
<span class="line"><span>  hosts (2):</span></span>
<span class="line"><span>    192.168.1.20</span></span>
<span class="line"><span>    192.168.1.30</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span></code></pre></div><p>本文就是这些了，我们成功演示了如何在 CentOS 8 和 RHEL 8 系统中安装和使用 Ansible。请分享你的反馈和意见。</p><hr>`,50)),l("p",null,[s[14]||(s[14]=n("via: ")),a(e,{href:"https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/"},{default:t(()=>s[13]||(s[13]=[n("https://www.linuxtechi.com/install-ansible-centos-8-rhel-8/")])),_:1})]),l("p",null,[s[19]||(s[19]=n("作者：")),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>s[15]||(s[15]=[n("Pradeep Kumar")])),_:1}),s[20]||(s[20]=n(" 选题：")),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>s[16]||(s[16]=[n("lujun9972")])),_:1}),s[21]||(s[21]=n(" 译者：")),a(e,{href:"https://github.com/geekpi"},{default:t(()=>s[17]||(s[17]=[n("geekpi")])),_:1}),s[22]||(s[22]=n(" 校对：")),a(e,{href:"https://github.com/wxy"},{default:t(()=>s[18]||(s[18]=[n("wxy")])),_:1})]),l("p",null,[s[25]||(s[25]=n("本文由 ")),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>s[23]||(s[23]=[n("LCTT")])),_:1}),s[26]||(s[26]=n(" 原创编译，")),a(e,{href:"https://linux.cn/"},{default:t(()=>s[24]||(s[24]=[n("Linux中国")])),_:1}),s[27]||(s[27]=n(" 荣誉推出"))])])}const A=p(r,[["render",u]]);export{k as __pageData,A as default};
